import { validate, ValidationResult } from './validator';

describe('validate', () => {
  // Test case for successful validation
  test('should return valid when all required fields are present and truthy', () => {
    const data = { name: 'Test', age: 30 };
    const schema = { required: ['name', 'age'] };
    const result = validate(data, schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  // Test case for missing required field
  test('should return invalid when a required field is missing', () => {
    const data = { name: 'Test' };
    const schema = { required: ['name', 'age'] };
    const result = validate(data, schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toContain('Missing required field: age');
  });

  // Test case for non-object input
  test('should return invalid for non-object input', () => {
    const schema = { required: ['name'] };
    const result = validate('string', schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toContain('Input must be an object');
  });

  // Test case to verify the fix: allowing falsy but valid values (0, "", false)
  test('should return valid when required fields are present but falsy (0, "", false)', () => {
    const data = { count: 0, description: "", isActive: false };
    const schema = { required: ['count', 'description', 'isActive'] };
    const result = validate(data, schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  // Test case for explicitly undefined field (should fail)
  test('should return invalid when a required field is explicitly undefined', () => {
    const data = { name: 'Test', age: undefined };
    const schema = { required: ['name', 'age'] };
    const result = validate(data, schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toContain('Missing required field: age');
  });
});

